import csv
import numpy as np
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer

rows = []
with open('/work/cdft_piezo_pool.csv') as f:
    for row in csv.DictReader(f):
        rows.append(row)

polar_pgs = {'1','2','m','mm2','4','4mm','3','3m','6','6mm'}

# continue from remaining polar
ids_done = {'c006','c007','c010','c011','c012','c013','c014','c016','c018','c020','c022','c023','c024','c025','c026','c028','c029','c032','c035','c037','c041','c042','c044','c047','c048'}

for r in rows:
    if r['candidate_id'] in ids_done:
        continue
    s = Structure.from_str(r['poscar'], fmt='poscar')
    try:
        sga = SpacegroupAnalyzer(s, symprec=0.1)
        pg = sga.get_point_group_symbol()
    except Exception as e:
        print(r['candidate_id'], r['formula'], 'FAIL at 0.1', e)
        continue
    if pg not in polar_pgs:
        continue
    sg = sga.get_space_group_symbol()

    seq = []
    for prec in [0.1, 0.2, 0.3, 0.5, 0.8, 1.0]:
        try:
            sga2 = SpacegroupAnalyzer(s, symprec=prec)
            sg2 = sga2.get_space_group_symbol()
            pg2 = sga2.get_point_group_symbol()
            centro_pgs = {'-1','2/m','mmm','4/m','4/mmm','-3','-3m','6/m','6/mmm','m-3','m-3m'}
            is_c = pg2 in centro_pgs
            if not seq or seq[-1][1] != sg2:
                seq.append((prec, sg2, is_c))
        except Exception as e:
            if not seq or seq[-1][1] != 'FAIL':
                seq.append((prec, 'FAIL', None))

    a,b,c = s.lattice.abc
    angs = s.lattice.angles
    abc_spread = (max(a,b,c)-min(a,b,c))/np.mean([a,b,c])
    ang_dev = max(abs(x-90) for x in angs)
    print(f"{r['candidate_id']} {r['formula']:12} {sg:10} spread={abc_spread:.3f} ang_dev={ang_dev:.1f}  sym={seq}")
